#!/usr/bin/env node
// Drift check for README.md's "See it run" fenced block, which claims to be "real output from
// examples/application's own `npm run docs`, not a mockup". Nothing enforced that claim: the
// example's committed goldens are regenerated by scripts/update-example-goldens.mjs, which never
// looks at README.md, so the counts and findings baked into the README's block could rot silently.
//
// This runs the example's own `docs` npm script (one source of truth for the commands) in an
// isolated temp copy, so nothing in the real examples/application tree is touched, and fails with
// a diff when the README's `$ npm run docs` block no longer says what that run prints. Blank lines
// are ignored, and the one line that prints an absolute, checkout-dependent path ("Wrote evidence
// model: <abs path>/docs/data.evidence.json") is compared by its relative tail, which is how the
// README shows it.
//
// examples/application is its own npm project with its own node_modules, installed by CI's
// `examples` job rather than by the root `npm ci`. It skips instead of failing when that folder
// is not installed, which keeps it safe in `npm run verify` on a checkout that never installed
// the examples, while still biting in CI where they are.
//
// Dependency-free (Node builtins only) -- dev/CI tooling, never shipped.

import { execFileSync } from "node:child_process"
import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  symlinkSync,
} from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const exampleDir = path.join(root, "examples/application")
const readmePath = path.join(root, "README.md")

if (!existsSync(path.join(exampleDir, "node_modules"))) {
  process.stdout.write(
    "[skip] examples/application: node_modules not installed (run `npm install` in examples/application first, or rely on CI's `examples` job, which does).\n",
  )
  process.exit(0)
}

/** Trimmed, non-blank lines, with the one absolute path the CLI prints reduced to its relative tail. */
function normalize(text) {
  return text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line !== "")
    .map((line) =>
      line.replace(/^(Wrote evidence model:) .*?(docs\/data\.evidence\.json)$/, "$1 $2"),
    )
}

function fail(message) {
  process.stderr.write(`\nREADME example drift: ${message}\n`)
  process.stderr.write(
    "The 'See it run' block in README.md no longer matches a fresh run of examples/application's\n" +
      "`npm run docs`. Run it yourself (`cd examples/application && npm run docs`), copy the current\n" +
      "output into the fenced block, and commit both.\n",
  )
  process.exitCode = 1
}

let fresh
try {
  fresh = mkdtempSync(path.join(tmpdir(), "data-cap-readme-example-"))
  // node_modules is symlinked back in below; docs/ and .env.example are regenerated by the run.
  const EXCLUDED_TOP_LEVEL = new Set(["node_modules", "docs", ".env.example"])
  cpSync(exampleDir, fresh, {
    recursive: true,
    filter: (src) => {
      const rel = path.relative(exampleDir, src)
      if (rel === "") return true
      const [top] = rel.split(path.sep)
      return !EXCLUDED_TOP_LEVEL.has(top)
    },
  })
  symlinkSync(path.join(exampleDir, "node_modules"), path.join(fresh, "node_modules"))
  mkdirSync(path.join(fresh, "docs"), { recursive: true })
  mkdirSync(path.join(fresh, "src/generated"), { recursive: true })

  const stdout = execFileSync("npm", ["run", "--silent", "docs"], {
    cwd: fresh,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    shell: process.platform === "win32",
  })

  const readme = readFileSync(readmePath, "utf8")
  const block = readme.match(/```text\n\$ npm run docs\n([\s\S]*?)\n```/)
  if (!block) {
    fail("could not find the '$ npm run docs' fenced block in README.md at all")
  } else {
    const expected = normalize(block[1])
    const actual = normalize(stdout)
    if (expected.join("\n") !== actual.join("\n")) {
      fail(
        `README says:\n${expected.map((l) => `  ${l}`).join("\n")}\n\nA fresh run prints:\n${actual.map((l) => `  ${l}`).join("\n")}`,
      )
    } else {
      process.stdout.write(`README example is fresh (${String(actual.length)} lines match).\n`)
    }
  }
} finally {
  if (fresh) rmSync(fresh, { recursive: true, force: true })
}
